def saisie():
    n = int(input("n="))
    while not 2 <= n <= 20:
        n = int(input("n="))
    return n


def verif_alpha(ch):
    ch = ch.upper()
    i = 0
    while i < len(ch) and ("A" <= ch[i] <= "Z" or ch[i] == " "):
        i = i + 1
    return len(ch) == i


def remplir(t, n):
    for i in range(n):
        t[i] = {}
        t[i]["np"] = input("np=")
        while t[i] == "" or verif_alpha(t[i]["np"]) == False:
            t[i]["np"] = input("np=")
        t[i]["grade"] = input("grade=")
        while not t[i]["grade"] in ["A", "B", "C", "D"]:
            t[i]["grade"] = input("grade=")
        t[i]["code"] = int(input("code="))
        while not t[i]["code"] > 0:
            t[i]["code"] = int(input("code="))
        t[i]["assi"] = input("assirence=")
        while not t[i]["assi"] in ["O", "N"]:
            t[i]["assi"] = input("assirence=")


def afficher(t, n):
    for i in range(n):
        print(t[i]["np"], t[i]["grade"], t[i]["code"], t[i]["assi"])
        input("")


def afficher_emp(t, n):

    grade = input("grade=")
    while not grade in ["A", "B", "C", "D"]:
        grade = input("grade=")
    nb = 0
    for i in range(n):
        if t[i]["grade"] == grade:
            nb += 1
    print("nbr grade de ", grade, "est ", nb)
    nbp = (nb * 100) / n
    print("persantage est ", nbp, "%")


